"""Ranked-choice tally. Usage: tally.py INPUT_DIR OUTPUT_FILE (rules in /app/docs)."""
import csv
import io
import json
import os
import sys


def norm_id(s):
    return str(s).strip().casefold()


def norm_text(s):
    s = str(s).casefold()
    s = "".join(ch if (ch.isalpha() or ch.isdigit()) else " " for ch in s)
    return " ".join(s.split())


def parse_revision(v):
    if isinstance(v, bool):
        return int(v)
    if isinstance(v, (int, float)):
        return int(v)
    return int(str(v).strip())


# ---------------------------------------------------------------- batch files

def read_csv_batch(path):
    with open(path, encoding="utf-8-sig", newline="") as f:
        text = f.read()
    meta = {}
    lines = text.splitlines(keepends=True)
    pos = 0
    n = len(lines)
    while pos < n:
        s = lines[pos].strip()
        if not s:
            pos += 1
            continue
        if s.startswith("#"):
            body = s[1:]
            if ":" in body:
                k, v = body.split(":", 1)
                meta[k.strip().lower()] = v.strip()
            pos += 1
            continue
        break
    rest = "".join(lines[pos:])
    reader = csv.reader(io.StringIO(rest, newline=""))
    header = None
    records = []
    for row in reader:
        if not row or all(not c.strip() for c in row):
            continue
        if header is None:
            header = [c.strip() for c in row]
            cols = {}
            rank_cols = []
            for i, name in enumerate(header):
                low = name.lower()
                if low not in cols:
                    cols[low] = i
                if low.startswith("rank") and low[4:].isdigit():
                    rank_cols.append((int(low[4:]), i))
            continue
        def get(i):
            return row[i] if i < len(row) else ""
        ballot = get(cols["ballot"]).strip() if "ballot" in cols else ""
        contest = get(cols["contest"]) if "contest" in cols else ""
        marks = []  # (rank, kind, value)
        for rank, i in rank_cols:
            cell = get(i)
            if not cell.strip():
                continue
            for m in cell.split("|"):
                if not m.strip():
                    continue
                ms = m.strip()
                if ms[:3].upper() == "WI:":
                    marks.append((rank, "w", ms[3:]))
                else:
                    marks.append((rank, "c", ms))
        records.append((ballot, contest.strip(), marks))
    return meta, records


def read_jsonl_batch(path):
    meta = None
    records = []
    with open(path, encoding="utf-8-sig") as f:
        for line in f:
            if not line.strip():
                continue
            obj = json.loads(line)
            if meta is None:
                meta = {str(k).lower(): v for k, v in obj.items()}
                continue
            marks = []
            for m in obj.get("marks") or []:
                try:
                    rank = int(m["rank"])
                except (KeyError, TypeError, ValueError):
                    continue
                if m.get("candidate") is not None:
                    marks.append((rank, "c", str(m["candidate"]).strip()))
                elif m.get("write_in") is not None:
                    marks.append((rank, "w", str(m["write_in"])))
            records.append((str(obj.get("ballot", "")), str(obj.get("contest", "")).strip(), marks))
    return meta or {}, records


def load_batches(input_dir):
    cvr = os.path.join(input_dir, "cvr")
    best = {}  # batch id -> (revision, status, records)
    if not os.path.isdir(cvr):
        return []
    for name in sorted(os.listdir(cvr)):
        path = os.path.join(cvr, name)
        if not os.path.isfile(path):
            continue
        if name.endswith(".csv"):
            meta, recs = read_csv_batch(path)
        elif name.endswith(".jsonl"):
            meta, recs = read_jsonl_batch(path)
        else:
            continue
        batch = str(meta.get("batch", "")).strip()
        rev = parse_revision(meta.get("revision", 1))
        status = str(meta.get("status", "final")).strip().lower()
        cur = best.get(batch)
        if cur is None or rev > cur[0]:
            best[batch] = (rev, status, recs)
    out = []
    for batch in sorted(best):
        rev, status, recs = best[batch]
        if status == "void":
            continue
        out.append(recs)
    return out


# ------------------------------------------------------------------- counting

class Contest:
    def __init__(self, c):
        self.id = c["id"]
        self.max_ranks = int(c["max_ranks"])
        self.ids = {}       # normalized id -> canonical id
        self.withdrawn = set()
        self.order = []     # canonical ids of counted candidates (file order)
        for cand in c.get("candidates", []):
            n = norm_id(cand["id"])
            self.ids[n] = cand["id"]
            if cand.get("status", "active") == "withdrawn":
                self.withdrawn.add(n)
            else:
                self.order.append(cand["id"])
        self.writein = {}   # normalized text -> normalized id
        for w in c.get("write_ins", []):
            n = norm_id(w["id"])
            self.ids[n] = w["id"]
            self.order.append(w["id"])
            for t in [w.get("name", "")] + list(w.get("aliases", [])):
                nt = norm_text(t)
                if nt:
                    self.writein.setdefault(nt, n)
        self.lot = [norm_id(x) for x in c.get("lot_order", [])]
        self.ballots = []   # list of ranking-type lists

    def read_ballot(self, marks):
        by_rank = {}
        for rank, kind, val in marks:
            if 1 <= rank <= self.max_ranks:
                by_rank.setdefault(rank, []).append((kind, val))
        seen = set()
        rankings = []
        for r in range(1, self.max_ranks + 1):
            cands = set()
            for kind, val in by_rank.get(r, []):
                if kind == "w":
                    t = self.writein.get(norm_text(val))
                    if t is not None:
                        cands.add(t)
                else:
                    n = norm_id(val)
                    if n in self.ids:
                        cands.add(n)
            if not cands:
                rankings.append(("skip", None))
                continue
            cands -= self.withdrawn
            if not cands:
                rankings.append(("pass", None))
                continue
            after_b = set(cands)
            cands -= seen
            seen |= after_b
            if not cands:
                rankings.append(("skip", None))
            elif len(cands) == 1:
                rankings.append(("choice", next(iter(cands))))
            else:
                rankings.append(("over", None))
        return rankings

    def add(self, marks):
        self.ballots.append(self.read_ballot(marks))

    def count_for(self, rankings, continuing):
        n = len(rankings)
        for i, (kind, cand) in enumerate(rankings):
            if kind == "choice":
                if cand in continuing:
                    return cand
            elif kind == "over":
                return None
            elif kind == "skip":
                if i + 1 < n and rankings[i + 1][0] == "skip":
                    return None
        return None

    def run(self):
        nballots = len(self.ballots)
        cont = [norm_id(x) for x in self.order]
        continuing = set(cont)
        canon = self.ids
        rounds = []
        history = []  # list of dicts of votes
        winner = None
        # collapse identical ballots
        groups = {}
        for b in self.ballots:
            groups[tuple(b)] = groups.get(tuple(b), 0) + 1
        items = list(groups.items())
        while True:
            votes = {c: 0 for c in continuing}
            for rk, cnt in items:
                c = self.count_for(rk, continuing)
                if c is not None:
                    votes[c] += cnt
            active = sum(votes.values())
            rnd = {"round": len(rounds) + 1,
                   "tallies": {canon[c]: votes[c] for c in cont if c in continuing},
                   "exhausted": nballots - active,
                   "eliminated": []}
            rounds.append(rnd)
            history.append(votes)
            if active == 0:
                break
            win = None
            for c in continuing:
                if votes[c] * 2 > active:
                    win = c
            if win is None and len(continuing) == 1:
                win = next(iter(continuing))
            if win is not None:
                winner = canon[win]
                break
            zeros = [c for c in continuing if votes[c] == 0]
            if zeros:
                elim = zeros
            else:
                low = min(votes.values())
                tied = [c for c in continuing if votes[c] == low]
                k = len(history) - 2
                while len(tied) > 1 and k >= 0:
                    m = min(history[k][c] for c in tied)
                    tied = [c for c in tied if history[k][c] == m]
                    k -= 1
                if len(tied) > 1:
                    def lotpos(c):
                        return self.lot.index(c) if c in self.lot else -1
                    tied = [max(tied, key=lotpos)]
                elim = tied
            rnd["eliminated"] = sorted(canon[c] for c in elim)
            continuing -= set(elim)
        return {"contest": self.id, "ballots": nballots, "winner": winner, "rounds": rounds}


def main():
    input_dir, output_file = sys.argv[1], sys.argv[2]
    with open(os.path.join(input_dir, "election.json"), encoding="utf-8-sig") as f:
        election = json.load(f)
    contests = [Contest(c) for c in election["contests"]]
    by_id = {}
    for c in contests:
        by_id.setdefault(c.id, c)
    for recs in load_batches(input_dir):
        for ballot, contest, marks in recs:
            c = by_id.get(contest)
            if c is not None:
                c.add(marks)
    result = {"election": election.get("election"),
              "contests": [c.run() for c in contests]}
    out_dir = os.path.dirname(os.path.abspath(output_file))
    os.makedirs(out_dir, exist_ok=True)
    with open(output_file, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=1)
        f.write("\n")


if __name__ == "__main__":
    main()
